13	struct TimelineView: View {
14	    @ObservedObject var timelineContext: TimelineViewModel.Context
15	    @State private var dragOver = false
16	    
17	    var body: some View {
18	        TimelineViewRepresentable()
19	            .id(timelineContext.viewState.roomID)
20	            // It is tempting to inject these environment values last to avoid also injecting them into the sheets,
21	            // and that approach works great on iOS. But it doesn't work on macOS (as of 15.5) where the app goes 💥
22	            .environmentObject(timelineContext)
23	            .environment(\.timelineContext, timelineContext)
24	            .environment(\.focussedEventID, timelineContext.viewState.timelineState.focussedEvent?.eventID)
25	            .alert(item: $timelineContext.alertInfo)
26	            .sheet(item: $timelineContext.manageMemberViewModel) {
27	                ManageRoomMemberSheetView(context: $0.context)
28	            }
29	            .sheet(item: $timelineContext.debugInfo) { TimelineItemDebugView(info: $0) }
30	            .sheet(item: $timelineContext.actionMenuInfo) { info in
31	                let actions = TimelineItemMenuActionProvider(timelineItem: info.item,
32	                                                             canCurrentUserSendMessage: timelineContext.viewState.canCurrentUserSendMessage,
33	                                                             canCurrentUserRedactSelf: timelineContext.viewState.canCurrentUserRedactSelf,
34	                                                             canCurrentUserRedactOthers: timelineContext.viewState.canCurrentUserRedactOthers,
35	                                                             canCurrentUserPin: timelineContext.viewState.canCurrentUserPin,
36	                                                             pinnedEventIDs: timelineContext.viewState.pinnedEventIDs,
37	                                                             isDM: timelineContext.viewState.isDirectOneToOneRoom,
38	                                                             isViewSourceEnabled: timelineContext.viewState.isViewSourceEnabled,
39	                                                             areThreadsEnabled: timelineContext.viewState.areThreadsEnabled,
40	                                                             timelineKind: timelineContext.viewState.timelineKind,
41	                                                             emojiProvider: timelineContext.viewState.emojiProvider)
42	                    .makeActions()
43	                if let actions {
44	                    TimelineItemMenu(item: info.item, actions: actions)
45	                        .environmentObject(timelineContext)
46	                }
47	            }
48	            .sheet(item: $timelineContext.reactionSummaryInfo) {
49	                ReactionsSummaryView(reactions: $0.reactions,
50	                                     members: timelineContext.viewState.members,
51	                                     mediaProvider: timelineContext.mediaProvider,
52	                                     selectedReactionKey: $0.selectedKey)
53	                    .edgesIgnoringSafeArea([.bottom])
54	            }
55	            .sheet(item: $timelineContext.readReceiptsSummaryInfo) {
56	                ReadReceiptsSummaryView(orderedReadReceipts: $0.orderedReceipts)
57	                    .environmentObject(timelineContext)
58	            }
59	            .translationPresentation(isPresented: $timelineContext.showTranslation, text: timelineContext.textToBeTranslated ?? "")
60	            .onChange(of: timelineContext.showTranslation) { oldValue, newValue in
61	                if oldValue, !newValue {
62	                    // clear texts after translation was dismissed
63	                    timelineContext.textToBeTranslated = nil
64	                }
65	            }
66	            .onDrop(of: ["public.item", "public.file-url"], isTargeted: $dragOver) { providers -> Bool in
67	                let supportedProviders = providers.filter(\.isSupportedForPasteOrDrop)
68	                
69	                guard !supportedProviders.isEmpty else {
70	                    return false
71	                }
72	                
73	                timelineContext.send(viewAction: .handlePasteOrDrop(providers: supportedProviders))
74	                return true
75	            }
76	    }
77	}
