79	/// A table view wrapper that displays the timeline of a room.
80	struct TimelineViewRepresentable: UIViewControllerRepresentable {
81	    @EnvironmentObject private var viewModelContext: TimelineViewModel.Context
82	
83	    func makeUIViewController(context: Context) -> TimelineTableViewController {
84	        TimelineTableViewController(coordinator: context.coordinator,
85	                                    isScrolledToBottom: $viewModelContext.isScrolledToBottom,
86	                                    floatingDateText: $viewModelContext.floatingDateText,
87	                                    scrollToBottomPublisher: viewModelContext.viewState.timelineState.scrollToBottomPublisher)
88	    }
89	    
90	    func updateUIViewController(_ uiViewController: TimelineTableViewController, context: Context) {
91	        context.coordinator.update(tableViewController: uiViewController)
92	    }
93	    
94	    func makeCoordinator() -> Coordinator {
95	        Coordinator(viewModelContext: viewModelContext)
96	    }
97	    
98	    // MARK: - Coordinator
99	    
100	    @MainActor
101	    class Coordinator {
102	        let context: TimelineViewModel.Context
103	        
104	        init(viewModelContext: TimelineViewModel.Context) {
105	            context = viewModelContext
106	        }
107	        
108	        /// Updates the specified table view's properties from the current view state.
109	        func update(tableViewController: TimelineTableViewController) {
110	            if tableViewController.isSwitchingTimelines != context.viewState.timelineState.isSwitchingTimelines {
111	                // Must come before timelineItemsDictionary in order to disable animations.
112	                tableViewController.isSwitchingTimelines = context.viewState.timelineState.isSwitchingTimelines
113	            }
114	            if tableViewController.timelineItemsDictionary != context.viewState.timelineState.itemsDictionary {
115	                tableViewController.timelineItemsDictionary = context.viewState.timelineState.itemsDictionary
116	            }
117	            if tableViewController.paginationState != context.viewState.timelineState.paginationState {
118	                tableViewController.paginationState = context.viewState.timelineState.paginationState
119	            }
120	            if tableViewController.isLive != context.viewState.timelineState.isLive {
121	                tableViewController.isLive = context.viewState.timelineState.isLive
122	            }
123	            if tableViewController.focussedEvent != context.viewState.timelineState.focussedEvent {
124	                tableViewController.focussedEvent = context.viewState.timelineState.focussedEvent
125	            }
126	            if tableViewController.hideTimelineMedia != context.viewState.hideTimelineMedia {
127	                tableViewController.hideTimelineMedia = context.viewState.hideTimelineMedia
128	            }
129	            
130	            if tableViewController.typingMembers.members != context.viewState.typingMembers {
131	                tableViewController.setTypingMembers(context.viewState.typingMembers)
132	            }
133	        }
134	        
135	        func send(viewAction: TimelineViewAction) {
136	            context.send(viewAction: viewAction)
137	        }
138	    }
139	}
