42	/// A table view controller that displays the timeline of a room.
43	///
44	/// This class subclasses `UIViewController` as `UITableViewController` adds some
45	/// extra keyboard handling magic that wasn't playing well with SwiftUI (as of iOS 16.1).
46	/// Also this TableViewController uses a **flipped tableview**
47	class TimelineTableViewController: UIViewController {
48	    private let coordinator: TimelineViewRepresentable.Coordinator
49	    private let tableView = UITableView(frame: .zero, style: .plain)
50	    
51	    var timelineItemsDictionary = OrderedDictionary<TimelineItemIdentifier.UniqueID, RoomTimelineItemViewState>() {
52	        didSet {
53	            guard canApplySnapshot else {
54	                hasPendingItems = true
55	                return
56	            }
57	            
58	            applySnapshot()
59	            
60	            if timelineItemsDictionary.isEmpty {
61	                paginatePublisher.send()
62	            }
63	            
64	            sendLastVisibleItemReadReceipt()
65	        }
66	    }
67	    
68	    /// Whether or not it is safe to update the data source with the latest items.
69	    private var canApplySnapshot: Bool {
70	        if isLive {
71	            // Backward pagination jumps if items are inserted whilst actively dragging.
72	            !isDraggingScrollView
73	        } else {
74	            // Forward pagination breaks inertial scrolling when fixing the offset.
75	            !scrollViewIsScrolling
76	        }
77	    }
78	    
79	    /// There are pending items in `timelineItemsDictionary` that haven't been applied to the data source.
80	    private var hasPendingItems = false
81	    
82	    /// The scroll view is scrolling either directly with a drag or indirectly with inertia.
83	    private var scrollViewIsScrolling = false {
84	        didSet {
85	            if !scrollViewIsScrolling, hasPendingItems, !isLive {
86	                hasPendingItems = false
87	                applySnapshot()
88	            }
89	        }
90	    }
91	    
92	    /// The scroll view is being dragged by the user (doesn't include scrolling with inertia)
93	    private var isDraggingScrollView = false {
94	        didSet {
95	            if !isDraggingScrollView, hasPendingItems, isLive {
96	                hasPendingItems = false
97	                applySnapshot()
98	            }
99	        }
100	    }
101	    
102	    /// Whether or not the current timeline is live or built around an event ID.
103	    var isLive = true {
104	        didSet {
105	            // Update isScrolledToBottom when switching back to a live timeline.
106	            if isLive { scrollViewDidScroll(tableView) }
107	        }
108	    }
109	    
110	    /// The state of pagination (in both directions) of the current timeline.
111	    var paginationState: TimelinePaginationState = .initial {
112	        didSet {
113	            // Paginate again if the threshold hasn't been satisfied.
114	            paginatePublisher.send(())
115	        }
116	    }
117	    
118	    /// Whether the table view is about to load items from a new timeline or not.
119	    var isSwitchingTimelines = false
120	    
121	    /// The focussed event if navigating to an event permalink within the room.
122	    var focussedEvent: TimelineState.FocussedEvent? {
123	        didSet {
124	            guard let focussedEvent, focussedEvent.appearance != .hasAppeared else { return }
125	            scrollToItem(eventID: focussedEvent.eventID, animated: focussedEvent.appearance == .animated)
126	        }
127	    }
128	    
129	    var hideTimelineMedia = false {
130	        didSet {
131	            guard let snapshot = dataSource?.snapshot() else { return }
132	            dataSource?.applySnapshotUsingReloadData(snapshot)
133	        }
134	    }
135	    
136	    /// Used to hold an observable object that the typing indicator can use
137	    let typingMembers = TypingMembersObservableObject(members: [])
138	    
139	    /// Updates the typing members but also updates table view items
140	    func setTypingMembers(_ members: [String]) {
141	        DispatchQueue.main.async {
142	            // Avoid `Publishing changes from within view update` warnings
143	            self.typingMembers.members = members
144	        }
145	    }
146	    
147	    @Binding private var isScrolledToBottom: Bool
148	    @Binding private var floatingDateText: String?
149	    
150	    /// A work item used to auto-hide the floating date badge after scrolling stops.
151	    private var floatingDateHideWorkItem: DispatchWorkItem?
152	
153	    private var timelineItemsIDs: [TimelineItemIdentifier.UniqueID] {
154	        timelineItemsDictionary.keys.elements.reversed()
155	    }
156	    
157	    /// The table's diffable data source.
158	    private var dataSource: UITableViewDiffableDataSource<TimelineSection, TimelineItemIdentifier.UniqueID>?
159	    private var cancellables = Set<AnyCancellable>()
160	
161	    /// A publisher used to throttle back pagination requests.
162	    ///
163	    /// Our view actions get wrapped in a `Task` so it is possible that a second call in
164	    /// quick succession can execute before ``paginationState`` acknowledges that
165	    /// pagination is in progress.
166	    private let paginatePublisher = PassthroughSubject<Void, Never>()
167	    
168	    /// A value to determine the scroll velocity threshold to detect a change in direction of the scroll view
169	    private let scrollVelocityThreshold: CGFloat = 50.0
170	    /// A publisher used to throttle scroll direction changes
171	    private let scrollDirectionPublisher = PassthroughSubject<ScrollDirection, Never>()
172	    /// Whether or not the view has been shown on screen yet.
173	    private var hasAppearedOnce = false
174	    
175	    /// Value that determines if the table view is flipped or not according to the VoiceOver status.
176	    private var scaleY: CGFloat {
177	        UIAccessibility.isVoiceOverRunning ? 1 : -1
178	    }
179	    
180	    init(coordinator: TimelineViewRepresentable.Coordinator,
181	         isScrolledToBottom: Binding<Bool>,
182	         floatingDateText: Binding<String?>,
183	         scrollToBottomPublisher: PassthroughSubject<Void, Never>) {
184	        self.coordinator = coordinator
185	        _isScrolledToBottom = isScrolledToBottom
186	        _floatingDateText = floatingDateText
187	        
188	        super.init(nibName: nil, bundle: nil)
189	        
190	        tableView.register(TimelineItemCell.self, forCellReuseIdentifier: TimelineItemCell.reuseIdentifier)
191	        tableView.register(TimelineTypingIndicatorCell.self, forCellReuseIdentifier: TimelineTypingIndicatorCell.reuseIdentifier)
192	        tableView.separatorStyle = .none
193	        tableView.allowsSelection = false
194	        tableView.keyboardDismissMode = .onDrag
195	        tableView.backgroundColor = .compound.bgCanvasDefault
196	        
197	        // The tableview should be flipped to display the newest items at the top
198	        // the only exception is VoiceOver, where we want to keep the latest item at the top as Android.
199	        tableView.transform = CGAffineTransform(scaleX: 1, y: scaleY)
200	        view.addSubview(tableView)
201	        
202	        // Prevents XCUITest from invoking the diffable dataSource's cellProvider
203	        // for each possible cell, causing layout issues
204	        tableView.accessibilityElementsHidden = ProcessInfo.shouldDisableTimelineAccessibility
205	        
206	        scrollToBottomPublisher
207	            .sink { [weak self] _ in
208	                self?.scrollToNewestItem(animated: true)
209	            }
210	            .store(in: &cancellables)
211	        
212	        paginatePublisher
213	            .collect(.byTime(DispatchQueue.main, 0.1))
214	            .sink { [weak self] _ in
215	                self?.paginateIfNeeded()
216	            }
217	            .store(in: &cancellables)
218	        
219	        scrollDirectionPublisher
220	            .throttle(for: 0.5, scheduler: DispatchQueue.main, latest: true)
221	            .removeDuplicates()
222	            .sink { direction in
223	                coordinator.send(viewAction: .hasScrolled(direction: direction))
224	            }
225	            .store(in: &cancellables)
226	        
227	        NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)
228	            .sink { [weak self] _ in
229	                self?.sendLastVisibleItemReadReceipt()
230	            }
231	            .store(in: &cancellables)
232	        
233	        // Observe voice over status changes to flip the table view accordingly
234	        NotificationCenter.default.publisher(for: UIAccessibility.voiceOverStatusDidChangeNotification)
235	            .sink { [weak self] _ in
236	                guard let self else { return }
237	                tableView.transform = CGAffineTransform(scaleX: 1, y: scaleY)
238	                tableView.reloadData()
239	            }
240	            .store(in: &cancellables)
241	        
242	        configureDataSource()
243	    }
244	    
245	    @available(*, unavailable)
246	    required init?(coder: NSCoder) {
247	        fatalError("init(coder:) is not available.")
248	    }
249	    
250	    override func viewWillAppear(_ animated: Bool) {
251	        super.viewWillAppear(animated)
252	        
253	        sendLastVisibleItemReadReceipt()
254	        
255	        guard !hasAppearedOnce else { return }
256	        tableView.contentOffset.y = -1
257	        hasAppearedOnce = true
258	        paginatePublisher.send()
259	    }
260	    
261	    override func viewWillLayoutSubviews() {
262	        super.viewWillLayoutSubviews()
263	        
264	        guard tableView.frame.size != view.frame.size else {
265	            return
266	        }
267	        
268	        tableView.frame = CGRect(origin: .zero, size: view.frame.size)
269	    }
270	    
271	    /// Configures a diffable data source for the timeline's table view.
272	    private func configureDataSource() {
273	        dataSource = .init(tableView: tableView) { [weak self] tableView, indexPath, id in
274	            switch id {
275	            case TimelineItemIdentifier.UniqueID(TimelineTypingIndicatorCell.reuseIdentifier):
276	                let cell = tableView.dequeueReusableCell(withIdentifier: TimelineTypingIndicatorCell.reuseIdentifier, for: indexPath)
277	                guard let self else {
278	                    return cell
279	                }
280	                
281	                cell.contentConfiguration = UIHostingConfiguration {
282	                    TypingIndicatorView(typingMembers: self.typingMembers)
283	                }
284	                .margins(.vertical, 0)
285	                .minSize(height: 0)
286	                .background(Color.clear)
287	                
288	                // Flipping the cell can create some issues with cell resizing, so flip the content View
289	                cell.contentView.transform = CGAffineTransform(scaleX: 1, y: scaleY)
290	                cell.accessibilityElements = [cell.contentView] // Ensure VoiceOver reads the content view only
291	                
292	                return cell
293	            default:
294	                let cell = tableView.dequeueReusableCell(withIdentifier: TimelineItemCell.reuseIdentifier, for: indexPath)
295	                guard let self, let cell = cell as? TimelineItemCell else { return cell }
296	                
297	                let viewState = timelineItemsDictionary[id]
298	                cell.item = viewState
299	                guard let viewState else {
300	                    return cell
301	                }
302	                
303	                cell.contentConfiguration = UIHostingConfiguration { [coordinator, hideTimelineMedia] in
304	                    RoomTimelineItemView(viewState: viewState)
305	                        .id(id)
306	                        .frame(maxWidth: .infinity, alignment: .leading)
307	                        .environmentObject(coordinator.context) // Attempted fix at a crash in TimelineItemContextMenu
308	                        .environment(\.timelineContext, coordinator.context)
309	                        .environment(\.shouldAutomaticallyLoadImages, !hideTimelineMedia)
310	                }
311	                .margins(.all, 0) // Margins are handled in the stylers
312	                .minSize(height: 1)
313	                .background(Color.clear)
314	                
315	                // Flipping the cell can create some issues with cell resizing, so flip the content View
316	                cell.contentView.transform = CGAffineTransform(scaleX: 1, y: scaleY)
317	                return cell
318	            }
319	        }
320	        
321	        // We only animate when there's a new last message, so its safe
322	        // to animate from the bottom (which is the top as we're flipped).
323	        dataSource?.defaultRowAnimation = (UIAccessibility.isReduceMotionEnabled ? .none : .top)
324	        tableView.delegate = self
325	        
326	        NotificationCenter.default.addObserver(self,
327	                                               selector: #selector(accessibilityReduceMotionDidChange),
328	                                               name: UIAccessibility.reduceMotionStatusDidChangeNotification,
329	                                               object: nil)
330	    }
331	    
332	    @objc private func accessibilityReduceMotionDidChange() {
333	        dataSource?.defaultRowAnimation = (UIAccessibility.isReduceMotionEnabled ? .none : .top)
334	    }
335	    
336	    /// Updates the table view with the latest items from the ``timelineItems`` array. After
337	    /// updating the data, the table will be scrolled to the bottom if it was visible otherwise
338	    /// the scroll position will be updated to maintain the position of the last visible item.
339	    private func applySnapshot() {
340	        guard let dataSource else { return }
341	
342	        var snapshot = NSDiffableDataSourceSnapshot<TimelineSection, TimelineItemIdentifier.UniqueID>()
343	        
344	        // We don't want to display the typing notification in this timeline
345	        if coordinator.context.viewState.timelineKind != .pinned {
346	            snapshot.appendSections([.typingIndicator])
347	            snapshot.appendItems([TimelineItemIdentifier.UniqueID(TimelineTypingIndicatorCell.reuseIdentifier)])
348	        }
349	        snapshot.appendSections([.main])
350	        snapshot.appendItems(timelineItemsIDs)
351	        
352	        let currentSnapshot = dataSource.snapshot()
353	        
354	        // We only animate when new items come at the end of a live timeline, ignoring transitions through empty.
355	        let newestItemIdentifier = snapshot.mainItemIdentifiers.first
356	        let currentNewestItemIdentifier = currentSnapshot.mainItemIdentifiers.first
357	        let newestItemIDChanged = snapshot.numberOfMainItems > 0 && currentSnapshot.numberOfMainItems > 0 && newestItemIdentifier != currentNewestItemIdentifier
358	        let animated = isLive && !isSwitchingTimelines && newestItemIDChanged
359	        
360	        let layout: Layout? = if !isLive, newestItemIDChanged {
361	            snapshotLayout()
362	        } else {
363	            nil
364	        }
365	        
366	        dataSource.apply(snapshot, animatingDifferences: animated)
367	        
368	        if let focussedEvent, focussedEvent.appearance != .hasAppeared {
369	            scrollToItem(eventID: focussedEvent.eventID, animated: focussedEvent.appearance == .animated)
370	        } else if let layout {
371	            restoreLayout(layout)
372	        } else if isSwitchingTimelines {
373	            scrollToNewestItem(animated: false)
374	        }
375	        
376	        if isSwitchingTimelines {
377	            coordinator.send(viewAction: .hasSwitchedTimeline)
378	        }
379	    }
380	    
381	    /// Scrolls to the newest item in the timeline.
382	    private func scrollToNewestItem(animated: Bool) {
383	        guard !timelineItemsIDs.isEmpty else {
384	            return
385	        }
386	        tableView.scrollToRow(at: IndexPath(item: 0, section: 0), at: .top, animated: animated)
387	        scrollDirectionPublisher.send(.bottom)
388	    }
389	
390	    /// Scrolls to the oldest item in the timeline.
391	    private func scrollToOldestItem(animated: Bool) {
392	        guard !timelineItemsIDs.isEmpty else {
393	            return
394	        }
395	        tableView.scrollToRow(at: IndexPath(item: timelineItemsIDs.count - 1, section: 1), at: .bottom, animated: animated)
396	        scrollDirectionPublisher.send(.top)
397	    }
398	    
399	    /// Scrolls to the item with the corresponding event ID if loaded in the timeline.
400	    private func scrollToItem(eventID: String, animated: Bool) {
401	        DispatchQueue.main.async { [weak self] in // Fixes #2805
402	            guard let self else { return }
403	            if let kvPair = timelineItemsDictionary.first(where: { $0.value.identifier.eventID == eventID }),
404	               let indexPath = dataSource?.indexPath(for: kvPair.key) {
405	                // Scrolling to the middle created a small bump in the timeline
406	                // Using top, which is bottom in the reversed timeline helps with rendering
407	                // in full long messages and images
408	                tableView.scrollToRow(at: indexPath, at: .top, animated: animated)
409	                coordinator.send(viewAction: .scrolledToFocussedItem)
410	                // Ensure VoiceOver focus happens after the scroll animation (if any)
411	                DispatchQueue.main.asyncAfter(deadline: .now() + (animated ? 0.5 : 0.0)) {
412	                    if let cell = self.tableView.cellForRow(at: indexPath) {
413	                        UIAccessibility.post(notification: .layoutChanged, argument: cell)
414	                    }
415	                }
416	            }
417	        }
418	    }
419	    
420	    /// Checks whether or not pagination is needed in either direction and requests one if so.
421	    ///
422	    /// **Note:** Prefer not to call this directly, instead using ``paginatePublisher`` to throttle requests.
