786	    private func buildTimelineViews(timelineItems: [RoomTimelineItemProtocol], isSwitchingTimelines: Bool = false) {
787	        var timelineItemsDictionary = OrderedDictionary<TimelineItemIdentifier.UniqueID, RoomTimelineItemViewState>()
788	        
789	        timelineItems.filter { $0 is RedactedRoomTimelineItem }.forEach { timelineItem in
790	            // Stops the audio player when a voice message is redacted.
791	            guard let playerState = mediaPlayerProvider.playerState(for: .timelineItemIdentifier(timelineItem.id)) else {
792	                return
793	            }
794	            
795	            Task { @MainActor in
796	                playerState.detachAudioPlayer()
797	                mediaPlayerProvider.unregister(audioPlayerState: playerState)
798	            }
799	        }
800	
801	        let itemsGroupedByTimelineDisplayStyle = timelineItems.chunked { current, next in
802	            canGroupItem(timelineItem: current, with: next)
803	        }
804	        
805	        for itemGroup in itemsGroupedByTimelineDisplayStyle {
806	            guard !itemGroup.isEmpty else {
807	                MXLog.error("Found empty item group")
808	                continue
809	            }
810	            
811	            if itemGroup.count == 1 {
812	                if let firstItem = itemGroup.first {
813	                    timelineItemsDictionary.updateValue(updateViewState(item: firstItem, groupStyle: .single),
814	                                                        forKey: firstItem.id.uniqueID)
815	                }
816	            } else {
817	                for (index, item) in itemGroup.enumerated() {
818	                    if index == 0 {
819	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .first),
820	                                                            forKey: item.id.uniqueID)
821	                    } else if index == itemGroup.count - 1 {
822	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .last),
823	                                                            forKey: item.id.uniqueID)
824	                    } else {
825	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .middle),
826	                                                            forKey: item.id.uniqueID)
827	                    }
828	                }
829	            }
830	        }
831	        
832	        if isSwitchingTimelines {
833	            state.timelineState.isSwitchingTimelines = true
834	        }
835	        
836	        state.timelineState.itemsDictionary = timelineItemsDictionary
837	    }
