839	    private func updateViewState(item: RoomTimelineItemProtocol, groupStyle: TimelineGroupStyle) -> RoomTimelineItemViewState {
840	        if let timelineItemViewState = state.timelineState.itemsDictionary[item.id.uniqueID] {
841	            timelineItemViewState.groupStyle = groupStyle
842	            timelineItemViewState.type = .init(item: item)
843	            return timelineItemViewState
844	        } else {
845	            return RoomTimelineItemViewState(item: item, groupStyle: groupStyle)
